package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.ByteArrayOutputStream;
import java.io.File;
import java.io.IOException;
import java.io.OutputStream;
import java.math.*;
import java.util.*;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveOutputStream;
import org.apache.commons.compress.archivers.tar.TarArchiveEntry;
import org.apache.commons.compress.archivers.tar.TarArchiveOutputStream;
import org.apache.commons.compress.archivers.tar.TarConstants;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class TarArchiveOutputStream_putArchiveEntry_TriageGen2Test {

    private ByteArrayOutputStream out;
    private TarArchiveOutputStream tarOut;

    @Before
    public void setUp() throws IOException {
        out = new ByteArrayOutputStream();
        tarOut = new TarArchiveOutputStream(out);
    }

    @Test
    public void testPutArchiveEntry_NormalName_File() throws IOException {
        String name = "test.txt";
        TarArchiveEntry entry = new TarArchiveEntry(name);
        entry.setSize(5);

        tarOut.putArchiveEntry(entry);

        // Verify state changes via side effects if possible, 
        // but here we mainly ensure no exception and header is written
        Assert.assertTrue(out.size() > 0);
        tarOut.closeArchiveEntry();
    }

    @Test
    public void testPutArchiveEntry_NormalName_Directory() throws IOException {
        String name = "test_dir";
        TarArchiveEntry entry = new TarArchiveEntry(name);
        // directory flag is usually set via constructor or specific methods in TarArchiveEntry

        tarOut.putArchiveEntry(entry);
        Assert.assertTrue(out.size() > 0);
        tarOut.closeArchiveEntry();
    }

    @Test
    public void testPutArchiveEntry_LongName_LongFileModeGNU() throws IOException {
        // Create a name longer than NAMELEN (100 bytes)
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < TarConstants.NAMELEN + 10; i++) {
            sb.append("a");
        }
        String longName = sb.toString();

        tarOut.setLongFileMode(TarArchiveOutputStream.LONGFILE_GNU);
        TarArchiveEntry entry = new TarArchiveEntry(longName);
        entry.setSize(5);

        tarOut.putArchiveEntry(entry);

        // In GNU mode, it should write the longlink entry first
        Assert.assertTrue(out.size() > 0);
        tarOut.closeArchiveEntry();
    }

    @Test(expected = RuntimeException.class)
    public void testPutArchiveEntry_LongName_ThrowsExceptionWhenNotGNUOrTruncate() throws IOException {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < TarConstants.NAMELEN + 10; i++) {
            sb.append("a");
        }
        String longName = sb.toString();

        // Default mode is usually NOT LONGFILE_GNU or LONGFILE_TRUNCATE
        tarOut.setLongFileMode(TarArchiveOutputStream.LONGFILE_DEFAULT);
        TarArchiveEntry entry = new TarArchiveEntry(longName);

        tarOut.putArchiveEntry(entry);
    }

    @Test
    public void testPutArchiveEntry_LongName_LongFileModeTruncate() throws IOException {
        // Note: The code provided shows: else if (longFileMode != LONGFILE_TRUNCATE) { throw ... }
        // This means if mode IS LONGFILE_TRUNCATE, it falls through to the standard write logic
        // without throwing an exception, effectively truncating the name logic-wise in the header.

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < TarConstants.NAMELEN + 10; i++) {
            sb.append("a");
        }
        String longName = sb.toString();

        tarOut.setLongFileMode(TarArchiveOutputStream.LONGFILE_TRUNCATE);
        TarArchiveEntry entry = new TarArchiveEntry(longName);
        entry.setSize(5);

        tarOut.putArchiveEntry(entry);
        Assert.assertTrue(out.size() > 0);
        tarOut.closeArchiveEntry();
    }

    @Test
    public void testPutArchiveEntry_SizeUpdateLogic() throws IOException {
        // Test the currSize update for files
        TarArchiveEntry fileEntry = new TarArchiveEntry("file.txt");
        fileEntry.setSize(123);
        tarOut.putArchiveEntry(fileEntry);
        // We can't access private currSize directly, but we ensure no crash
        tarOut.closeArchiveEntry();

        // Test the currSize update for directories
        TarArchiveEntry dirEntry = new TarArchiveEntry("dir/");
        // In TarArchiveEntry, directory status is usually checked via isDirectory()
        // We mock the behavior by using a name that implies directory if necessary, 
        // but TarArchiveEntry internal state is what matters.
        // Since we can't easily force isDirectory() without reflection or subclasses, 
        // we assume the standard TarArchiveEntry behavior.
        tarOut.putArchiveEntry(dirEntry);
        tarOut.closeArchiveEntry();
    }
}
